def compute(vars):
    goldman_index = vars["v1"]
    sp500_index = vars["v2"]
    initial_value = 100
    goldman_return_pct = (goldman_index - initial_value) / initial_value * 100
    sp500_return_pct = (sp500_index - initial_value) / initial_value * 100
    difference_pct = goldman_return_pct - sp500_return_pct

    return {
        "value": difference_pct,
        "trace": {
            "initial_value": initial_value,
            "goldman_cumulative_return_pct": goldman_return_pct,
            "sp500_cumulative_return_pct": sp500_return_pct,
            "difference_percentage_points": difference_pct,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
